  1	package com.clothing;
  2	
  3	import io.javalin.Javalin;
  4	import org.slf4j.Logger;
  5	import org.slf4j.LoggerFactory;
  6	
  7	public class Application {
  8	    private static final Logger logger = LoggerFactory.getLogger(Application.class);
  9	
 10	    public static void main(String[] args) {
 11	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "8080"));
 12	
 13	        Database.initialize();
 14	
 15	        var app = Javalin.create(config -> {
 16	            config.http.defaultContentType = "application/json";
 17	        }).start(port);
 18	
 19	        logger.info("Service started on port {}", port);
 20	
 21	        new OrderRoutes(app).register();
 22	        new ProductRoutes(app).register();
 23	        new CustomerRoutes(app).register();
 24	    }
 25	}
 26	package com.clothing;
 27	
 28	import com.clothing.model.*;
 29	import com.clothing.service.*;
 30	import io.javalin.Javalin;
 31	import org.slf4j.Logger;
 32	import org.slf4j.LoggerFactory;
 33	
 34	import java.math.BigDecimal;
 35	import java.time.Instant;
 36	
 37	public class OrderRoutes {
 38	    private static final Logger logger = LoggerFactory.getLogger(OrderRoutes.class);
 39	    private final Javalin app;
 40	    private final ProductRepository productRepo = new ProductRepository();
 41	    private final CustomerRepository customerRepo = new CustomerRepository();
 42	    private final OrderRepository orderRepo = new OrderRepository();
 43	    private final CheckoutService checkoutService = new CheckoutService(productRepo, customerRepo, orderRepo);
 44	
 45	    public OrderRoutes(Javalin app) {
 46	        this.app = app;
 47	    }
 48	
 49	    public void register() {
 50	        app.post("/checkout/summary", ctx -> {
 51	            try {
 52	                CheckoutRequest req = ctx.bodyAsClass(CheckoutRequest.class);
 53	                var validationError = Validation.validateCheckout(req, productRepo);
 54	                if (validationError != null) {
 55	                    ctx.status(validationError.httpStatus());
 56	                    ctx.json(new ErrorResponse(validationError.code()));
 57	                    return;
 58	                }
 59	
 60	                if (req.coupon() != null && !req.coupon().isEmpty()) {
 61	                    var couponError = Validation.validateCoupon(req.coupon(), req, productRepo, customerRepo);
 62	                    if (couponError != null) {
 63	                        ctx.status(couponError.httpStatus());
 64	                        ctx.json(new ErrorResponse(couponError.code()));
 65	                        return;
 66	                    }
 67	                }
 68	
 69	                Summary summary = checkoutService.calculateSummary(req);
 70	
 71	                var paymentError = Validation.validatePaymentMethodForTotal(req.paymentMethod(), summary.finalTotal());
 72	                if (paymentError != null) {
 73	                    ctx.status(paymentError.httpStatus());
 74	                    ctx.json(new ErrorResponse(paymentError.code()));
 75	                    return;
 76	                }
 77	
 78	                ctx.status(200);
 79	                ctx.json(summary);
 80	            } catch (Exception e) {
 81	                logger.error("Error in checkout summary", e);
 82	                ctx.status(500);
 83	                ctx.json(new ErrorResponse("INTERNAL_ERROR"));
 84	            }
 85	        });
 86	
 87	        app.post("/orders", ctx -> {
 88	            try {
 89	                CheckoutRequest req = ctx.bodyAsClass(CheckoutRequest.class);
 90	                var validationError = Validation.validateCheckout(req, productRepo);
 91	                if (validationError != null) {
 92	                    ctx.status(validationError.httpStatus());
 93	                    ctx.json(new ErrorResponse(validationError.code()));
 94	                    return;
 95	                }
 96	
 97	                if (req.coupon() != null && !req.coupon().isEmpty()) {
 98	                    var couponError = Validation.validateCoupon(req.coupon(), req, productRepo, customerRepo);
 99	                    if (couponError != null) {
100	                        ctx.status(couponError.httpStatus());
101	                        ctx.json(new ErrorResponse(couponError.code()));
102	                        return;
103	                    }
104	                }
105	
106	                Summary summary = checkoutService.calculateSummary(req);
107	
108	                var paymentError = Validation.validatePaymentMethodForTotal(req.paymentMethod(), summary.finalTotal());
109	                if (paymentError != null) {
110	                    ctx.status(paymentError.httpStatus());
111	                    ctx.json(new ErrorResponse(paymentError.code()));
112	                    return;
113	                }
114	
115	                Order order = checkoutService.registerOrder(req);
116	                ctx.status(201);
117	                ctx.json(order);
118	            } catch (Exception e) {
119	                logger.error("Error creating order", e);
120	                ctx.status(500);
121	                ctx.json(new ErrorResponse("INTERNAL_ERROR"));
122	            }
123	        });
124	
125	        app.get("/orders/{id}", ctx -> {
126	            try {
127	                long orderId = Long.parseLong(ctx.pathParam("id"));
128	                Order order = orderRepo.getOrder(orderId);
129	                if (order == null) {
130	                    ctx.status(404);
131	                    ctx.json(new ErrorResponse("ORDER_NOT_FOUND"));
132	                    return;
133	                }
134	                ctx.status(200);
135	                ctx.json(order);
136	            } catch (Exception e) {
137	                logger.error("Error getting order", e);
138	                ctx.status(500);
139	                ctx.json(new ErrorResponse("INTERNAL_ERROR"));
140	            }
141	        });
142	
143	        app.post("/orders/{id}/payment", ctx -> {
144	            try {
145	                long orderId = Long.parseLong(ctx.pathParam("id"));
146	                PaymentRequest paymentReq = ctx.bodyAsClass(PaymentRequest.class);
147	
148	                if (paymentReq.transactionId() == null || paymentReq.paidAt() == null) {
149	                    ctx.status(422);
150	                    ctx.json(new ErrorResponse("INVALID_ORDER"));
151	                    return;
152	                }
153	
154	                Order order = orderRepo.getOrder(orderId);
155	                if (order == null) {
156	                    ctx.status(404);
157	                    ctx.json(new ErrorResponse("ORDER_NOT_FOUND"));
158	                    return;
159	                }
160	
161	                if (order.status() != OrderStatus.AWAITING_PAYMENT) {
162	                    ctx.status(409);
163	                    ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED"));
164	                    return;
165	                }
166	
167	                if (orderRepo.isPaymentAlreadyRecorded(orderId, paymentReq.transactionId())) {
168	                    ctx.status(200);
169	                    ctx.json(order);
170	                    return;
171	                }
172	
173	                Instant paidAt = Instant.parse(paymentReq.paidAt());
174	
175	                // Check for stock availability
176	                String cpf = orderRepo.getCustomerCpfForOrder(orderId);
177	                for (OrderItem item : order.items()) {
178	                    int currentStock = orderRepo.getStockForProduct(item.sku());
179	                    if (currentStock < item.quantity()) {
180	                        orderRepo.updateOrderStatus(orderId, OrderStatus.CANCELLED);
181	                        customerRepo.createNotification(cpf, orderId, NotificationType.ORDER_CANCELLED);
182	                        ctx.status(409);
183	                        ctx.json(new ErrorResponse("INSUFFICIENT_STOCK"));
184	                        return;
185	                    }
186	                }
187	
188	                try {
189	                    checkoutService.processPayment(orderId, paymentReq.transactionId(), paidAt, order, cpf);
190	                    Order updatedOrder = orderRepo.getOrder(orderId);
191	                    ctx.status(200);
192	                    ctx.json(updatedOrder);
193	                } catch (Exception e) {
194	                    if (e.getMessage() != null && e.getMessage().equals("ORDER_EXPIRED")) {
195	                        ctx.status(409);
196	                        ctx.json(new ErrorResponse("ORDER_EXPIRED"));
197	                        return;
198	                    }
199	                    throw e;
200	                }
201	            } catch (Exception e) {
202	                logger.error("Error processing payment", e);
203	                ctx.status(500);
204	                ctx.json(new ErrorResponse("INTERNAL_ERROR"));
205	            }
206	        });
207	
208	        app.post("/orders/{id}/shipment", ctx -> {
209	            try {
210	                long orderId = Long.parseLong(ctx.pathParam("id"));
211	                ShipmentRequest shipmentReq = ctx.bodyAsClass(ShipmentRequest.class);
212	
213	                if (shipmentReq.trackingCode() == null) {
214	                    ctx.status(422);
215	                    ctx.json(new ErrorResponse("INVALID_ORDER"));
216	                    return;
217	                }
218	
219	                Order order = orderRepo.getOrder(orderId);
220	                if (order == null) {
221	                    ctx.status(404);
222	                    ctx.json(new ErrorResponse("ORDER_NOT_FOUND"));
223	                    return;
224	                }
225	
226	                if (order.status() != OrderStatus.PAID) {
227	                    ctx.status(409);
228	                    ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED"));
229	                    return;
230	                }
231	
232	                orderRepo.setTrackingCode(orderId, shipmentReq.trackingCode());
233	                orderRepo.updateOrderStatusAndTimestamp(orderId, OrderStatus.SHIPPED, "shipped_at");
234	
235	                Order updatedOrder = orderRepo.getOrder(orderId);
236	                ctx.status(200);
237	                ctx.json(updatedOrder);
238	            } catch (Exception e) {
239	                logger.error("Error shipping order", e);
240	                ctx.status(500);
241	                ctx.json(new ErrorResponse("INTERNAL_ERROR"));
242	            }
243	        });
244	
245	        app.post("/orders/{id}/delivery", ctx -> {
246	            try {
247	                long orderId = Long.parseLong(ctx.pathParam("id"));
248	
249	                Order order = orderRepo.getOrder(orderId);
250	                if (order == null) {
251	                    ctx.status(404);
252	                    ctx.json(new ErrorResponse("ORDER_NOT_FOUND"));
253	                    return;
254	                }
255	
256	                if (order.status() != OrderStatus.SHIPPED) {
257	                    ctx.status(409);
258	                    ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED"));
259	                    return;
260	                }
261	
262	                orderRepo.updateOrderStatusAndTimestamp(orderId, OrderStatus.DELIVERED, "delivered_at");
263	
264	                Order updatedOrder = orderRepo.getOrder(orderId);
265	                ctx.status(200);
266	                ctx.json(updatedOrder);
267	            } catch (Exception e) {
268	                logger.error("Error delivering order", e);
269	                ctx.status(500);
270	                ctx.json(new ErrorResponse("INTERNAL_ERROR"));
271	            }
272	        });
273	
274	        app.post("/orders/{id}/cancellation", ctx -> {
275	            try {
276	                long orderId = Long.parseLong(ctx.pathParam("id"));
277	
278	                Order order = orderRepo.getOrder(orderId);
279	                if (order == null) {
280	                    ctx.status(404);
281	                    ctx.json(new ErrorResponse("ORDER_NOT_FOUND"));
282	                    return;
283	                }
284	
285	                if (order.status() == OrderStatus.SHIPPED || order.status() == OrderStatus.DELIVERED) {
286	                    ctx.status(409);
287	                    ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED"));
288	                    return;
289	                }
290	
291	                String cpf = orderRepo.getCustomerCpfForOrder(orderId);
292	
293	                if (order.status() == OrderStatus.PAID) {
294	                    for (OrderItem item : order.items()) {
295	                        orderRepo.incrementStock(item.sku(), item.quantity());
296	                    }
297	
298	                    BigDecimal credit = order.summary().nextPurchaseCredit();
299	                    if (credit.compareTo(java.math.BigDecimal.ZERO) > 0) {
300	                        customerRepo.updateCreditBalance(cpf, credit.negate());
301	                    }
302	                }
303	
304	                orderRepo.updateOrderStatus(orderId, OrderStatus.CANCELLED);
305	                customerRepo.createNotification(cpf, orderId, NotificationType.ORDER_CANCELLED);
306	
307	                Order updatedOrder = orderRepo.getOrder(orderId);
308	                ctx.status(200);
309	                ctx.json(updatedOrder);
310	            } catch (Exception e) {
311	                logger.error("Error cancelling order", e);
312	                ctx.status(500);
313	                ctx.json(new ErrorResponse("INTERNAL_ERROR"));
314	            }
315	        });
316	    }
317	}

