257	public class Validation {
258	    private static final Logger logger = LoggerFactory.getLogger(Validation.class);
259	    private static final Pattern ZIP_PATTERN = Pattern.compile("^\\d{8}$");
260	
261	    public record ValidationError(String code, int httpStatus) {}
262	
263	    public static ValidationError validateCheckout(CheckoutRequest req, ProductRepository products) {
264	        if (req.customer() == null || req.customer().cpf() == null || req.customer().cpf().isEmpty() ||
265	            req.customer().email() == null || req.customer().email().isEmpty()) {
266	            return new ValidationError("INVALID_ORDER", 422);
267	        }
268	
269	        if (req.items() == null || req.items().isEmpty()) {
270	            return new ValidationError("INVALID_ORDER", 422);
271	        }
272	
273	        Set<String> seenSkus = new HashSet<>();
274	        for (OrderItem item : req.items()) {
275	            if (item.sku() == null || item.sku().isEmpty() || item.quantity() <= 0) {
276	                return new ValidationError("INVALID_ORDER", 422);
277	            }
278	            if (!seenSkus.add(item.sku())) {
279	                return new ValidationError("INVALID_ORDER", 422);
280	            }
281	        }
282	
283	        for (OrderItem item : req.items()) {
284	            Product product = products.findBySku(item.sku());
285	            if (product == null) {
286	                return new ValidationError("UNKNOWN_PRODUCT", 422);
287	            }
288	            if (product.discontinued()) {
289	                return new ValidationError("PRODUCT_DISCONTINUED", 422);
290	            }
291	            if (product.stock() < item.quantity()) {
292	                return new ValidationError("INSUFFICIENT_STOCK", 422);
293	            }
294	        }
295	
296	        if (req.clubTier() == null) {
297	            return new ValidationError("INVALID_CLUB_TIER", 422);
298	        }
299	
300	        if (req.region() == null) {
301	            return new ValidationError("INVALID_REGION", 422);
302	        }
303	
304	        if (req.zipCode() == null || !ZIP_PATTERN.matcher(req.zipCode()).matches()) {
305	            return new ValidationError("INVALID_ZIP_CODE", 422);
306	        }
307	
308	        if (req.shippingMethod() == null) {
309	            return new ValidationError("INVALID_SHIPPING_METHOD", 422);
310	        }
311	
312	        double totalWeightKg = calculateTotalWeight(req.items(), products);
313	        if (req.shippingMethod() == ShippingMethod.COURIER && totalWeightKg > 5) {
314	            return new ValidationError("SHIPPING_METHOD_UNAVAILABLE", 422);
315	        }
316	
317	        if (req.shippingMethod() == ShippingMethod.ECONOMY || req.shippingMethod() == ShippingMethod.EXPRESS) {
318	            try {
319	                String service = req.shippingMethod() == ShippingMethod.ECONOMY ? "STD" : "EXP";
320	                var quote = TransLogClient.quote(req.zipCode(), totalWeightKg, service);
321	                if (quote == null) {
322	                    return new ValidationError("SHIPPING_METHOD_UNAVAILABLE", 422);
323	                }
324	            } catch (TransLogClient.CarrierUnavailableException e) {
325	                return new ValidationError("CARRIER_UNAVAILABLE", 503);
326	            }
327	        }
328	
329	        if (req.coupon() != null && !req.coupon().isEmpty()) {
330	            if (!isValidCoupon(req.coupon())) {
331	                return new ValidationError("INVALID_COUPON", 422);
332	            }
333	        }
334	
335	        if (req.paymentMethod() == null) {
336	            return new ValidationError("INVALID_PAYMENT_METHOD", 422);
337	        }
338	
339	        int installments = req.getInstallmentsOrDefault();
340	        if (req.paymentMethod() == PaymentMethod.PIX || req.paymentMethod() == PaymentMethod.BANK_SLIP) {
341	            if (installments != 1) {
342	                return new ValidationError("INVALID_INSTALLMENTS", 422);
343	            }
344	        } else if (req.paymentMethod() == PaymentMethod.CREDIT_CARD) {
345	            if (installments < 1 || installments > 12) {
346	                return new ValidationError("INVALID_INSTALLMENTS", 422);
347	            }
348	        }
349	
350	        return null;
351	    }
