353	    public static ValidationError validateCoupon(String coupon, CheckoutRequest req, ProductRepository products, CustomerRepository customers) {
354	        if (coupon == null || coupon.isEmpty()) {
355	            return null;
356	        }
357	
358	        if (!isValidCoupon(coupon)) {
359	            return new ValidationError("INVALID_COUPON", 422);
360	        }
361	
362	        switch (coupon) {
363	            case "WELCOME10":
364	                var existingOrders = customers.findCompletedOrders(req.customer().cpf());
365	                if (!existingOrders.isEmpty()) {
366	                    return new ValidationError("COUPON_NOT_APPLICABLE", 422);
367	                }
368	                break;
369	
370	            case "MINUS50":
371	                var subtotal = calculateSubtotal(req.items(), products);
372	                if (subtotal.compareTo(new java.math.BigDecimal("300.00")) < 0) {
373	                    return new ValidationError("COUPON_NOT_APPLICABLE", 422);
374	                }
375	                break;
376	
377	            case "FREESHIPPING":
378	                if (req.shippingMethod() == ShippingMethod.STORE_PICKUP) {
379	                    return new ValidationError("COUPON_NOT_APPLICABLE", 422);
380	                }
381	                break;
382	
383	            case "BUY3PAY2":
384	                break;
385	        }
386	
387	        return null;
388	    }
389	
390	    public static ValidationError validatePaymentMethodForTotal(PaymentMethod method, java.math.BigDecimal total) {
391	        if (method == PaymentMethod.BANK_SLIP && total.compareTo(new java.math.BigDecimal("1000.00")) > 0) {
392	            return new ValidationError("PAYMENT_METHOD_UNAVAILABLE", 422);
393	        }
394	        return null;
395	    }
396	
397	    private static boolean isValidCoupon(String code) {
398	        return code != null && (code.equals("WELCOME10") || code.equals("MINUS50") ||
399	               code.equals("FREESHIPPING") || code.equals("BUY3PAY2"));
400	    }
