402	    private static double calculateTotalWeight(List<OrderItem> items, ProductRepository products) {
403	        double total = 0;
404	        for (OrderItem item : items) {
405	            Product product = products.findBySku(item.sku());
406	            if (product != null) {
407	                total += product.weightKg().doubleValue() * item.quantity();
408	            }
409	        }
410	        return total;
411	    }
