413	    private static java.math.BigDecimal calculateSubtotal(List<OrderItem> items, ProductRepository products) {
414	        var subtotal = new java.math.BigDecimal("0");
415	        for (OrderItem item : items) {
416	            Product product = products.findBySku(item.sku());
417	            if (product != null) {
418	                subtotal = Money.add(subtotal, Money.multiply(product.price(), new java.math.BigDecimal(item.quantity())));
419	            }
420	        }
421	        return subtotal;
422	    }
