208	            case GOLD -> Money.multiply(subtotal, new BigDecimal("0.05"));
209	        };
210	    }
211	
212	    private boolean shouldGetGift(CheckoutRequest req, BigDecimal subtotal) {
213	        return req.clubTier() == ClubTier.GOLD && subtotal.compareTo(new BigDecimal("500.00")) > 0;
214	    }
215	
216	    public Order registerOrder(CheckoutRequest req) {
217	        Summary summary = calculateSummary(req);
218	        customerRepo.findOrCreate(req.customer().cpf(), req.customer().email());
219	        return orderRepo.createOrder(req, summary);
220	    }
221	
222	    public void processPayment(long orderId, String transactionId, Instant paidAt, Order order, String cpf) throws Exception {
223	        Instant createdAt = orderRepo.getOrderCreatedAt(orderId);
224	        if (createdAt != null) {
225	            long diffSeconds = java.time.temporal.ChronoUnit.SECONDS.between(createdAt, paidAt);
226	            if (diffSeconds > 48 * 3600) {
227	                orderRepo.updateOrderStatus(orderId, OrderStatus.CANCELLED);
228	                customerRepo.createNotification(cpf, orderId, NotificationType.ORDER_CANCELLED);
229	                throw new Exception("ORDER_EXPIRED");
230	            }
231	        }
232	
233	        orderRepo.recordPayment(orderId, transactionId, paidAt);
234	        orderRepo.updateOrderStatusAndTimestamp(orderId, OrderStatus.PAID, "paid_at");
235	
236	        for (OrderItem item : order.items()) {
237	            orderRepo.decrementStock(item.sku(), item.quantity());
238	        }
239	
240	        BigDecimal credit = order.summary().nextPurchaseCredit();
241	        if (credit.compareTo(BigDecimal.ZERO) > 0) {
242	            customerRepo.updateCreditBalance(cpf, credit);
243	        }
244	
245	        customerRepo.createNotification(cpf, orderId, NotificationType.PAYMENT_APPROVED);
246	    }
247	}
248	package com.clothing.service;
249	
250	import com.clothing.model.*;
251	import org.slf4j.Logger;
252	import org.slf4j.LoggerFactory;
253	
254	import java.util.*;
255	import java.util.regex.Pattern;
256	
257	public class Validation {
258	    private static final Logger logger = LoggerFactory.getLogger(Validation.class);
259	    private static final Pattern ZIP_PATTERN = Pattern.compile("^\\d{8}$");
260	
261	    public record ValidationError(String code, int httpStatus) {}
262	
263	    public static ValidationError validateCheckout(CheckoutRequest req, ProductRepository products) {
264	        if (req.customer() == null || req.customer().cpf() == null || req.customer().cpf().isEmpty() ||
265	            req.customer().email() == null || req.customer().email().isEmpty()) {
266	            return new ValidationError("INVALID_ORDER", 422);
267	        }
268	
269	        if (req.items() == null || req.items().isEmpty()) {
270	            return new ValidationError("INVALID_ORDER", 422);
271	        }
272	
273	        Set<String> seenSkus = new HashSet<>();
274	        for (OrderItem item : req.items()) {
275	            if (item.sku() == null || item.sku().isEmpty() || item.quantity() <= 0) {
276	                return new ValidationError("INVALID_ORDER", 422);
277	            }
278	            if (!seenSkus.add(item.sku())) {
279	                return new ValidationError("INVALID_ORDER", 422);
280	            }
281	        }
282	
283	        for (OrderItem item : req.items()) {
284	            Product product = products.findBySku(item.sku());
285	            if (product == null) {
286	                return new ValidationError("UNKNOWN_PRODUCT", 422);
287	            }
288	            if (product.discontinued()) {
289	                return new ValidationError("PRODUCT_DISCONTINUED", 422);
290	            }
291	            if (product.stock() < item.quantity()) {
292	                return new ValidationError("INSUFFICIENT_STOCK", 422);
293	            }
294	        }
295	
296	        if (req.clubTier() == null) {
297	            return new ValidationError("INVALID_CLUB_TIER", 422);
298	        }
299	
300	        if (req.region() == null) {
301	            return new ValidationError("INVALID_REGION", 422);
302	        }
303	
304	        if (req.zipCode() == null || !ZIP_PATTERN.matcher(req.zipCode()).matches()) {
305	            return new ValidationError("INVALID_ZIP_CODE", 422);
306	        }
307	
308	        if (req.shippingMethod() == null) {
309	            return new ValidationError("INVALID_SHIPPING_METHOD", 422);
310	        }
311	
312	        double totalWeightKg = calculateTotalWeight(req.items(), products);
313	        if (req.shippingMethod() == ShippingMethod.COURIER && totalWeightKg > 5) {
314	            return new ValidationError("SHIPPING_METHOD_UNAVAILABLE", 422);
315	        }
316	
317	        if (req.shippingMethod() == ShippingMethod.ECONOMY || req.shippingMethod() == ShippingMethod.EXPRESS) {
318	            try {
319	                String service = req.shippingMethod() == ShippingMethod.ECONOMY ? "STD" : "EXP";
320	                var quote = TransLogClient.quote(req.zipCode(), totalWeightKg, service);
321	                if (quote == null) {
322	                    return new ValidationError("SHIPPING_METHOD_UNAVAILABLE", 422);
323	                }
324	            } catch (TransLogClient.CarrierUnavailableException e) {
325	                return new ValidationError("CARRIER_UNAVAILABLE", 503);
326	            }
327	        }
328	
329	        if (req.coupon() != null && !req.coupon().isEmpty()) {
330	            if (!isValidCoupon(req.coupon())) {
331	                return new ValidationError("INVALID_COUPON", 422);
332	            }
333	        }
334	
335	        if (req.paymentMethod() == null) {
336	            return new ValidationError("INVALID_PAYMENT_METHOD", 422);
337	        }
338	
339	        int installments = req.getInstallmentsOrDefault();
340	        if (req.paymentMethod() == PaymentMethod.PIX || req.paymentMethod() == PaymentMethod.BANK_SLIP) {
341	            if (installments != 1) {
342	                return new ValidationError("INVALID_INSTALLMENTS", 422);
343	            }
344	        } else if (req.paymentMethod() == PaymentMethod.CREDIT_CARD) {
345	            if (installments < 1 || installments > 12) {
346	                return new ValidationError("INVALID_INSTALLMENTS", 422);
347	            }
348	        }
349	
350	        return null;
351	    }
352	
353	    public static ValidationError validateCoupon(String coupon, CheckoutRequest req, ProductRepository products, CustomerRepository customers) {
354	        if (coupon == null || coupon.isEmpty()) {
355	            return null;
356	        }
357	
358	        if (!isValidCoupon(coupon)) {
359	            return new ValidationError("INVALID_COUPON", 422);
360	        }
361	
362	        switch (coupon) {
363	            case "WELCOME10":
364	                var existingOrders = customers.findCompletedOrders(req.customer().cpf());
365	                if (!existingOrders.isEmpty()) {
366	                    return new ValidationError("COUPON_NOT_APPLICABLE", 422);
367	                }
368	                break;
369	
370	            case "MINUS50":
371	                var subtotal = calculateSubtotal(req.items(), products);
372	                if (subtotal.compareTo(new java.math.BigDecimal("300.00")) < 0) {
373	                    return new ValidationError("COUPON_NOT_APPLICABLE", 422);
374	                }
375	                break;
376	
377	            case "FREESHIPPING":
378	                if (req.shippingMethod() == ShippingMethod.STORE_PICKUP) {
379	                    return new ValidationError("COUPON_NOT_APPLICABLE", 422);
380	                }
381	                break;
382	
383	            case "BUY3PAY2":
384	                break;
385	        }
386	
387	        return null;
388	    }
389	
390	    public static ValidationError validatePaymentMethodForTotal(PaymentMethod method, java.math.BigDecimal total) {
391	        if (method == PaymentMethod.BANK_SLIP && total.compareTo(new java.math.BigDecimal("1000.00")) > 0) {
392	            return new ValidationError("PAYMENT_METHOD_UNAVAILABLE", 422);
393	        }
394	        return null;
395	    }
396	
397	    private static boolean isValidCoupon(String code) {
398	        return code != null && (code.equals("WELCOME10") || code.equals("MINUS50") ||
399	               code.equals("FREESHIPPING") || code.equals("BUY3PAY2"));
400	    }
401	
402	    private static double calculateTotalWeight(List<OrderItem> items, ProductRepository products) {
403	        double total = 0;
404	        for (OrderItem item : items) {
405	            Product product = products.findBySku(item.sku());
406	            if (product != null) {
407	                total += product.weightKg().doubleValue() * item.quantity();
408	            }
409	        }
410	        return total;
411	    }
412	
413	    private static java.math.BigDecimal calculateSubtotal(List<OrderItem> items, ProductRepository products) {
414	        var subtotal = new java.math.BigDecimal("0");
415	        for (OrderItem item : items) {
416	            Product product = products.findBySku(item.sku());
417	            if (product != null) {
418	                subtotal = Money.add(subtotal, Money.multiply(product.price(), new java.math.BigDecimal(item.quantity())));
419	            }
420	        }
421	        return subtotal;
422	    }
423	}

