126	    private static HikariDataSource dataSource;
127	
128	    public static void initialize() {
129	        String url = System.getenv("DB_URL");
130	        String user = System.getenv("DB_USER");
131	        String password = System.getenv("DB_PASSWORD");
132	
133	        if (url == null || user == null || password == null) {
134	            throw new IllegalStateException("DB_URL, DB_USER and DB_PASSWORD environment variables must be set");
135	        }
136	
137	        HikariConfig config = new HikariConfig();
138	        config.setJdbcUrl(url);
139	        config.setUsername(user);
140	        config.setPassword(password);
141	        config.setMaximumPoolSize(10);
142	        config.setAutoCommit(true);
143	
144	        dataSource = new HikariDataSource(config);
145	        logger.info("Database connection pool created");
146	
147	        createSchema();
148	    }
149	
150	    private static void createSchema() {
151	        try (Connection conn = dataSource.getConnection()) {
152	            conn.createStatement().execute(
153	                "CREATE TABLE IF NOT EXISTS products (" +
154	                "sku VARCHAR(20) PRIMARY KEY, " +
155	                "name VARCHAR(255) NOT NULL, " +
156	                "price NUMERIC(10,2) NOT NULL, " +
157	                "weight_kg NUMERIC(5,2) NOT NULL, " +
158	                "stock INT NOT NULL, " +
159	                "discontinued BOOLEAN NOT NULL DEFAULT FALSE)"
160	            );
161	
162	            conn.createStatement().execute(
163	                "CREATE TABLE IF NOT EXISTS customers (" +
164	                "cpf VARCHAR(11) PRIMARY KEY, " +
165	                "email VARCHAR(255) NOT NULL, " +
166	                "credit_balance NUMERIC(10,2) NOT NULL DEFAULT 0, " +
167	                "created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP)"
168	            );
169	
170	            conn.createStatement().execute(
171	                "CREATE TABLE IF NOT EXISTS orders (" +
172	                "id BIGSERIAL PRIMARY KEY, " +
173	                "customer_cpf VARCHAR(11) NOT NULL, " +
174	                "status VARCHAR(20) NOT NULL, " +
175	                "products_subtotal NUMERIC(10,2) NOT NULL, " +
176	                "coupon_discount NUMERIC(10,2) NOT NULL, " +
177	                "shipping_cost NUMERIC(10,2) NOT NULL, " +
178	                "delivery_days INT NOT NULL, " +
179	                "insurance NUMERIC(10,2) NOT NULL, " +
180	                "payment_adjustment NUMERIC(10,2) NOT NULL, " +
181	                "final_total NUMERIC(10,2) NOT NULL, " +
182	                "club_tier VARCHAR(10) NOT NULL, " +
183	                "region VARCHAR(20) NOT NULL, " +
184	                "shipping_method VARCHAR(20) NOT NULL, " +
185	                "payment_method VARCHAR(20) NOT NULL, " +
186	                "installments INT NOT NULL, " +
187	                "next_purchase_credit NUMERIC(10,2) NOT NULL, " +
188	                "gift BOOLEAN NOT NULL, " +
189	                "tracking_code VARCHAR(50), " +
190	                "created_at TIMESTAMP NOT NULL, " +
191	                "paid_at TIMESTAMP, " +
192	                "shipped_at TIMESTAMP, " +
193	                "delivered_at TIMESTAMP)"
194	            );
195	
196	            conn.createStatement().execute(
197	                "CREATE TABLE IF NOT EXISTS order_items (" +
198	                "id BIGSERIAL PRIMARY KEY, " +
199	                "order_id BIGINT NOT NULL, " +
200	                "sku VARCHAR(20) NOT NULL, " +
201	                "quantity INT NOT NULL, " +
202	                "FOREIGN KEY (order_id) REFERENCES orders(id))"
203	            );
204	
205	            conn.createStatement().execute(
206	                "CREATE TABLE IF NOT EXISTS notifications (" +
207	                "id BIGSERIAL PRIMARY KEY, " +
208	                "customer_cpf VARCHAR(11) NOT NULL, " +
209	                "order_id BIGINT NOT NULL, " +
210	                "type VARCHAR(30) NOT NULL, " +
211	                "status VARCHAR(10) NOT NULL, " +
212	                "created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, " +
213	                "FOREIGN KEY (customer_cpf) REFERENCES customers(cpf), " +
214	                "FOREIGN KEY (order_id) REFERENCES orders(id))"
215	            );
216	
217	            conn.createStatement().execute(
218	                "CREATE TABLE IF NOT EXISTS payment_transactions (" +
219	                "id BIGSERIAL PRIMARY KEY, " +
220	                "order_id BIGINT NOT NULL UNIQUE, " +
221	                "transaction_id VARCHAR(100) NOT NULL UNIQUE, " +
222	                "paid_at TIMESTAMP NOT NULL, " +
223	                "FOREIGN KEY (order_id) REFERENCES orders(id))"
224	            );
225	
226	            conn.createStatement().execute(
227	                "CREATE INDEX IF NOT EXISTS idx_orders_cpf ON orders(customer_cpf)"
228	            );
229	
230	            conn.createStatement().execute(
231	                "CREATE INDEX IF NOT EXISTS idx_notifications_cpf ON notifications(customer_cpf)"
232	            );
233	
234	            logger.info("Database schema created");
235	        } catch (SQLException e) {
236	            throw new RuntimeException("Failed to create schema", e);
237	        }
238	
239	        seedInitialProducts();
240	    }
241	
242	    private static void seedInitialProducts() {
243	        try (Connection conn = dataSource.getConnection()) {
244	            var rs = conn.createStatement().executeQuery("SELECT COUNT(*) as count FROM products");
245	            rs.next();
246	            if (rs.getInt("count") == 0) {
247	                conn.createStatement().execute(
248	                    "INSERT INTO products (sku, name, price, weight_kg, stock, discontinued) VALUES " +
249	                    "('CAM-001', 'Camiseta básica', 79.90, 0.30, 50, false), " +
250	                    "('TEN-001', 'Tênis corrida', 249.90, 1.20, 10, false), " +
251	                    "('FON-001', 'Fone sem fio', 199.90, 0.25, 5, false), " +
252	                    "('MEI-001', 'Meia esportiva', 19.90, 0.10, 100, false), " +
253	                    "('JAQ-001', 'Jaqueta corta-vento', 389.90, 0.80, 3, false), " +
254	                    "('MOC-001', 'Mochila urbana', 159.90, 0.90, 1, false), " +
255	                    "('BON-001', 'Boné aba reta', 59.90, 0.15, 0, false), " +
256	                    "('REL-001', 'Relógio digital', 129.90, 0.20, 8, true)"
257	                );
258	                logger.info("Initial products seeded");
259	            }
260	        } catch (SQLException e) {
261	            throw new RuntimeException("Failed to seed products", e);
262	        }
263	    }
264	
265	    public static Connection getConnection() throws SQLException {
266	        return dataSource.getConnection();
267	    }
268	
269	    public static void close() {
270	        if (dataSource != null) {
271	            dataSource.close();
272	        }
273	    }
274	}

