    14	import java.time.Duration;
    15	
    16	public class TransLogClient {
    17	    private static final Logger logger = LoggerFactory.getLogger(TransLogClient.class);
    18	    private static final ObjectMapper mapper = new ObjectMapper();
    19	    private static final HttpClient httpClient = HttpClient.newHttpClient();
    20	
    21	    public record ShippingQuote(BigDecimal price, int deliveryDays) {}
    22	
    23	    public static ShippingQuote quote(String zipCode, double weightKg, String service) throws CarrierUnavailableException {
    24	        String translogUrl = System.getenv("TRANSLOG_URL");
    25	        if (translogUrl == null) {
    26	            throw new CarrierUnavailableException();
    27	        }
    28	
    29	        int weightGrams = (int) Math.round(weightKg * 1000);
    30	        String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s", translogUrl, zipCode, weightGrams, service);
    31	
    32	        try {
    33	            var request = HttpRequest.newBuilder()
    34	                .uri(URI.create(url))
    35	                .timeout(Duration.ofSeconds(2))
    36	                .GET()
    37	                .build();
    38	
    39	            var response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
    40	
    41	            if (response.statusCode() != 200) {
    42	                logger.warn("TransLog returned status {}", response.statusCode());
    43	                throw new CarrierUnavailableException();
    44	            }
    45	
    46	            JsonNode node = mapper.readTree(response.body());
    47	
    48	            if (node.has("error")) {
    49	                return null;
    50	            }
    51	
    52	            if (!node.has("price_cents") || !node.has("eta_hours")) {
    53	                throw new CarrierUnavailableException();
    54	            }
    55	
    56	            long priceCents = node.get("price_cents").asLong();
    57	            BigDecimal priceReais = Money.divide(new BigDecimal(priceCents), new BigDecimal("100"));
    58	
    59	            int hoursEta = node.get("eta_hours").asInt();
    60	            int deliveryDays = (int) Math.ceil((double) hoursEta / 24);
    61	
    62	            return new ShippingQuote(priceReais, deliveryDays);
    63	        } catch (IOException | InterruptedException e) {
    64	            logger.error("Failed to contact TransLog", e);
    65	            throw new CarrierUnavailableException();
    66	        }
    67	    }
    68	
    69	    public static class CarrierUnavailableException extends Exception {
    70	        public CarrierUnavailableException() {
    71	            super("Carrier unavailable");
    72	        }
    73	    }
    74	}
